  1	/**
  2	 * La selección de proveedor para un ítem de trabajo: entre los candidatos
  3	 * que las fuentes declaran, participan sólo los que la política permite,
  4	 * se descartan los no elegibles para la capacidad y la clase pedidas, y el
  5	 * orden lo decide la política con una estrategia de `ComboRouter`. El
  6	 * primero gana; sin ninguno, la ejecución queda bloqueada con la causa de
  7	 * cada candidato.
  8	 *
  9	 * El selector no conoce a ningún proveedor por su nombre: un proveedor
 10	 * local, una API remota o `claude-cli` son candidatos con el mismo contrato.
 11	 * Ningún proveedor es respaldo obligatorio: el lote tiene que poder
 12	 * ejecutarse sin claude-cli. La
 13	 * elegibilidad la trae cada candidato de su fuente —una cualificación
 14	 * aprobada, o la causa de no tenerla—, y el selector sólo la lee.
 15	 *
 16	 * Política:
 17	 *
 18	 *   { "strategy": "priority",
 19	 *     "allowed": [
 20	 *       { "provider": "local-qwen-coder", "priority": 10, "match": { "repository": "Qwen/…" } },
 21	 *       { "provider": "deepseek-api", "priority": 20 } ] }
 22	 *
 23	 * `priority` ordena de menor a mayor; `strategy` es una de
 24	 * `COMBO_STRATEGIES` y se aplica sobre ese orden (`priority`, la de por
 25	 * defecto, lo conserva). `match` acota por atributos del candidato, sin
 26	 * distinguir mayúsculas.
 27	 */
 28	
 29	import { COMBO_STRATEGIES, isComboStrategy, type ComboRouter, type ComboStrategy } from '../proxy/combo/comboRouter.ts'
 30	
 31	export type Locality = 'local' | 'remote'
 32	
 33	export type Eligibility =
 34	  | { readonly eligible: true, readonly evidence: string }
 35	  | { readonly eligible: false, readonly reason: string }
 36	
 37	export interface ProviderCandidate {
 38	  /** El nombre con que la política permite al proveedor. */
 39	  readonly provider: string
 40	  readonly model: string
 41	  /** Identidad única del candidato; con ella se midió su cualificación. */
 42	  readonly name: string
 43	  readonly locality: Locality
 44	  /** El mecanismo que lo ejecuta: `ollama`, `openai-compatible`, `claude-cli`… */
 45	  readonly adapter: string
 46	  /** Lo que un selector puede acotar: repositorio, cuantización, fuente… */
 47	  readonly attributes: Readonly<Record<string, string>>
 48	  readonly eligibility: Eligibility
 49	}
 50	
 51	export interface AllowedProvider {
 52	  readonly provider: string
 53	  readonly priority: number
 54	  readonly weight?: number
 55	  readonly match?: Readonly<Record<string, string>>
 56	}
 57	
 58	export interface ProviderPolicy {
 59	  readonly strategy: ComboStrategy
 60	  readonly allowed: readonly AllowedProvider[]
 61	}
 62	
 63	export type ProviderSelection =
 64	  | (Omit<ProviderCandidate, 'eligibility' | 'attributes'> & { readonly status: 'selected', readonly selectionReason: string })
 65	  | { readonly status: 'blocked', readonly blockedReason: string }
 66	
 67	export class ProviderPolicyError extends Error {
 68	  constructor(message: string) {
 69	    super(message)
 70	    this.name = 'ProviderPolicyError'
 71	  }
 72	}
 73	
 74	const DEFAULT_STRATEGY: ComboStrategy = 'priority'
 75	const SELECTION_GROUP = 'provider-selection'
 76	
 77	export function parseProviderPolicy(text: string): ProviderPolicy {
 78	  const document = parseObject(text)
 79	  if (document.fallback !== undefined) {
 80	    throw new ProviderPolicyError('`fallback` se retiró: ningún proveedor es respaldo obligatorio; cada proveedor permitido se lista en `allowed` con su prioridad')
 81	  }
 82	  const strategy = document.strategy ?? DEFAULT_STRATEGY
 83	  if (!isComboStrategy(strategy)) throw new ProviderPolicyError(`strategy «${String(strategy)}» no es ${COMBO_STRATEGIES.join(', ')}`)
 84	  if (!Array.isArray(document.allowed)) throw new ProviderPolicyError('`allowed` es la lista de proveedores permitidos')
 85	  return { strategy, allowed: document.allowed.map(allowedProviderOf) }
 86	}
 87	
 88	/** Elige el proveedor de un ítem: permitido por la política, elegible, y primero en el orden que la política declara. */
 89	export async function selectProvider(candidates: readonly ProviderCandidate[], policy: ProviderPolicy, router: ComboRouter): Promise<ProviderSelection> {
 90	  const permitted = candidates.flatMap(candidate => {
 91	    const selector = bestSelectorFor(candidate, policy)
 92	    return selector === undefined ? [] : [{ candidate, selector }]
 93	  })
 94	  if (permitted.length === 0) {
 95	    return { status: 'blocked', blockedReason: `ningún candidato de los proveedores permitidos: ${policy.allowed.map(selector => selector.provider).join(', ') || '(ninguno)'}` }
 96	  }
 97	  const rejected = permitted.filter(({ candidate }) => !candidate.eligibility.eligible).map(({ candidate }) => rejectionOf(candidate))
 98	  const eligible = permitted.filter(({ candidate }) => candidate.eligibility.eligible).sort((left, right) => left.selector.priority - right.selector.priority)
 99	  const ordered = await router.order(policy.strategy, SELECTION_GROUP, eligible.map(entry => ({
100	    ...entry, executionKey: entry.candidate.name, modelStr: entry.candidate.model, provider: entry.candidate.provider, weight: entry.selector.weight ?? 1,
101	  })))
102	  const [winner] = ordered
103	  if (winner === undefined) return { status: 'blocked', blockedReason: `ningún proveedor permitido es elegible: ${rejected.join('; ')}` }
104	  return selectionOf(winner.candidate, winner.selector, policy.strategy, rejected)
105	}
106	
107	/** El selector permitido que casa con el candidato; si casan varios, el de mayor preferencia. */
108	function bestSelectorFor(candidate: ProviderCandidate, policy: ProviderPolicy): AllowedProvider | undefined {
109	  return policy.allowed
110	    .filter(selector => selector.provider === candidate.provider && matchesAttributes(selector, candidate))
111	    .sort((left, right) => left.priority - right.priority)[0]
112	}
113	
114	function matchesAttributes(selector: AllowedProvider, candidate: ProviderCandidate): boolean {
115	  return Object.entries(selector.match ?? {}).every(([key, value]) => (candidate.attributes[key] ?? '').toLowerCase() === value.toLowerCase())
116	}
117	
118	function rejectionOf(candidate: ProviderCandidate): string {
119	  return `${candidate.name}: ${candidate.eligibility.eligible ? 'elegible' : candidate.eligibility.reason}`
120	}
121	
122	function selectionOf(candidate: ProviderCandidate, selector: AllowedProvider, strategy: ComboStrategy, rejected: readonly string[]): ProviderSelection {
123	  const evidence = candidate.eligibility.eligible ? candidate.eligibility.evidence : ''
124	  const discarded = rejected.length === 0 ? '' : `; descartados: ${rejected.join('; ')}`
125	  const { eligibility: _eligibility, attributes: _attributes, ...identity } = candidate
126	  return { ...identity, status: 'selected', selectionReason: `${candidate.name}: prioridad ${selector.priority} (estrategia ${strategy}), ${evidence}${discarded}` }
127	}
128	
129	function allowedProviderOf(value: unknown, index: number): AllowedProvider {
130	  if (!isObject(value)) throw new ProviderPolicyError(`allowed[${index}]: se espera un objeto`)
131	  if (typeof value.provider !== 'string' || value.provider === '') throw new ProviderPolicyError(`allowed[${index}].provider: se espera el nombre del proveedor`)
132	  if (typeof value.priority !== 'number' || !Number.isFinite(value.priority)) throw new ProviderPolicyError(`allowed[${index}].priority: se espera un número`)
133	  if (value.weight !== undefined && (typeof value.weight !== 'number' || value.weight < 0)) throw new ProviderPolicyError(`allowed[${index}].weight: se espera un número no negativo`)
134	  return {
135	    provider: value.provider,
136	    priority: value.priority,
137	    ...(value.weight === undefined ? {} : { weight: value.weight as number }),
138	    ...(value.match === undefined ? {} : { match: matchOf(value.match, index) }),
139	  }
140	}
141	
142	function matchOf(value: unknown, index: number): Readonly<Record<string, string>> {
143	  if (!isObject(value) || !Object.values(value).every(item => typeof item === 'string')) {
144	    throw new ProviderPolicyError(`allowed[${index}].match: se espera un objeto de atributos de texto`)
145	  }
146	  return value as Record<string, string>
147	}
148	
149	function parseObject(text: string): Record<string, unknown> {
150	  let document: unknown
151	  try {
152	    document = JSON.parse(text) as unknown
153	  } catch (error) {
154	    throw new ProviderPolicyError(`política ilegible: ${(error as Error).message}`)
155	  }
156	  if (!isObject(document)) throw new ProviderPolicyError('la política es un objeto JSON')
157	  return document
158	}
159	
160	function isObject(value: unknown): value is Record<string, unknown> {
161	  return typeof value === 'object' && value !== null && !Array.isArray(value)
162	}

