--- bunfig
# El preload del grifo de /tmp.
#
# `bun test <archivo>` suelto no pasa por `tests/run.sh`, asi que no heredaria
# el `TMPDIR` de la ejecucion. Este preload le da uno propio y lo retira al salir.
# El mecanismo y su guarda de propiedad: `tests/preload/tmpdir.ts`.
[test]
# `store.ts` va DESPUES: copia el store en el TMPDIR que `tmpdir.ts` declara.
preload = ["./tests/preload/tmpdir.ts", "./tests/preload/store.ts"]

# La raíz ejecuta typecheck sobre consumidores que importan los workspaces por
# nombre. El linker isolated no crea esos enlaces en node_modules raíz y cambia
# el universo medido (H-THYROX-154); declararlo aquí hace reproducible el mismo
# grafo sin depender de un flag manual de `bun install`.
[install]
linker = "hoisted"
--- tsconfig
{
  "compilerOptions": {
    "lib": ["ESNext"],
    "target": "ESNext",
    "module": "Preserve",
    "moduleResolution": "bundler",
    "customConditions": ["@thyrox/source"],
    "types": ["bun"],
    "strict": true,
    "noUncheckedIndexedAccess": true,
    "noUnusedLocals": true,
    "noUnusedParameters": true,
    "noFallthroughCasesInSwitch": true,
    "skipLibCheck": true,
    "noEmit": true,
    "allowImportingTsExtensions": true,
    "jsx": "react-jsx"
  },
  "include": ["src/**/*.ts", "src/**/*.tsx", "tests/**/*.ts"]
}
